mapper.select:
SELECT p.live_post_idx, p.board_group_idx, p.user_id, p.content, p.created_at, m.USER_NAME AS writer FROM tb_live_post p JOIN members m ON p.user_id = m.USER_ID where p.board_group_idx = #{boardGroupIdx}
AND p.live_post_idx < #{beforePostIdx}
ORDER BY p.live_post_idx DESC LIMIT #{limit}
